for (const [key, source] of lessons) {
  const objective = objectives[key];
  if (!objective) throw new Error(`Falta el objetivo educativo de ${key}.`);
  source.objective = objective;
  source.practiceGoals = [objective];
}
for (const [keys, complexity] of costs) for (const key of keys.split(" ")) {
  const source = lessons.get(key);
  if (source) source.complexity = complexity;
}

